import React, { useRef, useState } from 'react'
import Button from '../Button/Button'
import Checkbox from '../Checkbox/Checkbox'
import type { CheckboxGroupProps } from '../Checkbox/Group'

export default {
  title: 'Components/Checkbox Group',
  component: Checkbox.Group,
  argTypes: {
    ariaLabel: {
      control: { type: 'text' },
      description:
        "If a visible label isn't specified for a CheckboxGroup (using <Checkbox.Label> or another method), an aria-label must be provided for accessibility.\n\nOnly use this if a visual label on the checkbox group is not present. Note: Checkbox elements within a group should always have a visible label.",
    },
    direction: {
      control: { type: 'select', options: ['col', 'row'] },
      description: 'Layout direction for the checkbox group items',
    },
    error: {
      control: { type: 'boolean' },
      description: 'Whether the checkbox group is in an error state',
    },
    helperText: {
      control: { type: 'text' },
      description:
        'Helper text to display with the checkbox group. This will appear visually under the checkbox group',
    },
    label: {
      control: { type: 'text' },
      description:
        'Label for the checkbox group. This will appear visually next to the checkbox group',
    },
  },
}

function Template(args: CheckboxGroupProps & { label?: string }): JSX.Element {
  const props = { ...args, label: undefined }

  return (
    <Checkbox.Group {...props}>
      {args.label ? <Checkbox.Label>{args.label}</Checkbox.Label> : null}
      <Checkbox.Input color="primary">Client Name</Checkbox.Input>
      <Checkbox.Input color="primary">Appointment Date</Checkbox.Input>
      <Checkbox.Input color="primary">Appointment Id</Checkbox.Input>
    </Checkbox.Group>
  )
}

export const Default = {
  render: Template,
  args: {
    helperText: 'Selected columns will appear in the report',
    label: 'Columns to Include:',
  },
}

export function SelectAll(): JSX.Element {
  const [allSelected, setAllSelected] = useState(false)

  const checkboxRefs = useRef({})
  const selectingAll = useRef(false)

  const handleSelectAllColumns = () => {
    // find the checkboxes
    const unchecked = Object.keys(checkboxRefs.current).filter(
      (name) => !checkboxRefs.current[name].checked,
    )

    selectingAll.current = true
    // update the checkboxes
    if (unchecked.length > 0) {
      unchecked.forEach((name) => {
        checkboxRefs.current[name].checked = true
      })
    } else {
      Object.keys(checkboxRefs.current).forEach((name) => {
        checkboxRefs.current[name].checked = false
      })
    }

    selectingAll.current = false

    setAllSelected(unchecked.length !== 0)
  }

  const register = (checkbox) => {
    if (checkbox?.name) {
      checkboxRefs.current[checkbox.name] = checkbox
    }
  }

  const handleClick = () => {
    if (!selectingAll.current) {
      const unchecked = Object.keys(checkboxRefs.current).filter(
        (name) => !checkboxRefs.current[name].checked,
      )

      setAllSelected(unchecked.length === 0)
    }
  }

  return (
    <div className="space-y-2">
      <Button color="primary" onClick={handleSelectAllColumns} variant="text">
        {allSelected ? 'Unselect All' : 'Select All'}
      </Button>
      <Checkbox.Group>
        <Checkbox.Label>Columns to Include:</Checkbox.Label>
        <Checkbox.Input inputRef={register} name="name" onChange={handleClick}>
          Client Name
        </Checkbox.Input>
        <Checkbox.Input inputRef={register} name="date" onChange={handleClick}>
          Appointment Date
        </Checkbox.Input>
        <Checkbox.Input inputRef={register} name="id" onChange={handleClick}>
          Appointment Id
        </Checkbox.Input>
      </Checkbox.Group>
    </div>
  )
}
